import { useEffect, useRef, useState } from "react";
import { lerp, clamp, ease } from "./helpers";

const QUESTIONS = [
  { img: "/assets/question1.png", text: "Which segments are the most risk-prone?" },
  { img: "/assets/question2.png", text: "Where are the risk hotspots across the country?" },
  { img: "/assets/question3.png", text: "What correlations exist between risk rates and other factors?" },
];

const PEOPLE = [
  { label: "Truck drivers",     riskRate: "4.75%", meanAge: "30.90", img: "/assets/truck_driver.png" },
  { label: "Dark Store Workers", riskRate: "2.36%", meanAge: "24.34", img: "/assets/store.png" },
  { label: "Delivery Partners",  riskRate: "3.04%", meanAge: "27.94", img: "/assets/delivery.png" },
];

const SOURCE_LINK_STYLE = { color: "rgba(255,255,255,0.58)", textDecoration: "underline" };

// ─── Mobile layout: static stacked, unchanged from original ───────────────────
function MobileLayout() {
  const headingStyle = {
    fontFamily: "'Inter', sans-serif",
    fontWeight: 700,
    color: "white",
    textAlign: "center",
    margin: 0,
    fontSize: "30px",
    lineHeight: "40.86px",
    letterSpacing: "-0.04em",
  };

  return (
    <div style={{ background: "black", padding: "85px 16px 48px", position: "relative" }}>
      {/* Ellipse */}
      <div style={{ position: "absolute", top: 0, right: -430, zIndex: 0, pointerEvents: "none" }}>
        <img src="/assets/Ellipse.png" alt="" style={{ width: "900px", height: "900px" }} />
      </div>

      {/* ── Part 1 ── */}
      <div style={{ position: "relative", zIndex: 1, textAlign: "center", marginBottom: 24 }}>
        <h2 style={{ ...headingStyle, marginBottom: 8 }}>
          The Fraud Behind<br />the Workforce
        </h2>
        <p style={{ color: "white", fontSize: "12px", fontWeight: 600, margin: "0 0 12px", textAlign: "center", fontFamily: "'Inter', sans-serif", lineHeight: "18px" }}>
          India's gig workforce has grown from
        </p>
        <img src="/assets/graph.gif" alt="Gig workforce growth chart" style={{ width: "100%", display: "block", borderRadius: 4 }} />
        <div style={{ textAlign: "center", marginTop: 6, marginBottom: 4 }}>
          <span style={{ color: "rgba(255,255,255,0.38)", fontSize: 10, fontFamily: "'Inter', sans-serif" }}>
            Source:{" "}
            <a href="https://www.niti.gov.in/sites/default/files/2023-06/Policy_Brief_India%27s_Booming_Gig_and_Platform_Economy_27062022.pdf" target="_blank" rel="noreferrer" style={SOURCE_LINK_STYLE}>Niti Ayog</a>
            {" "}and{" "}
            <a href="https://www.livemint.com/money/personal-finance/indias-gig-economy-in-2025-growth-formalisation-and-financial-inclusion-explained-11753438649777.html" target="_blank" rel="noreferrer" style={SOURCE_LINK_STYLE}>Mint</a>
          </span>
        </div>
        <p style={{ color: "white", fontSize: "13px", fontFamily: "'Inter', sans-serif", textAlign: "center", margin: "8px 0 20px", lineHeight: "18px" }}>
          But as the workforce expands, fraud scales alongside it.
        </p>
      </div>

      {/* Divider 1 */}
      <div style={{ width: "100%", height: 1, background: "rgba(255,255,255,0.12)", marginBottom: 20, position: "relative", zIndex: 1 }} />

      {/* ── Part 2 ── */}
      <div style={{ position: "relative", zIndex: 1, marginBottom: 20 }}>
        <h2 style={{ ...headingStyle, marginBottom: 20 }}>
          This section<br />answers questions like
        </h2>
        <div style={{ display: "grid", gridTemplateColumns: "1fr", gap: 12 }}>
          {QUESTIONS.map((q, i) => (
            <div key={i} style={{ backgroundImage: "linear-gradient(#1d1d1d, #212121)", border: "1px solid rgba(255,255,255,0.2)", borderRadius: 16, padding: "14px", display: "flex", alignItems: "center", gap: 12, minHeight: 70 }}>
              <div style={{ width: 48, height: 48, flexShrink: 0, borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center" }}>
                <img src={q.img} alt="" style={{ width: 80, height: 56, objectFit: "contain" }} />
              </div>
              <p style={{ color: "white", fontSize: "13px", fontWeight: 500, margin: 0, lineHeight: 1.5, fontFamily: "'Inter', sans-serif" }}>{q.text}</p>
            </div>
          ))}
        </div>
      </div>

      {/* Divider 2 */}
      <div style={{ width: "100%", height: 1, background: "rgba(255,255,255,0.08)", marginBottom: 20, position: "relative", zIndex: 1 }} />

      {/* ── Part 3 ── */}
      <div style={{ position: "relative", zIndex: 1 }}>
        <h2 className="bg-gradient-to-r from-[#cdcdcd] to-white bg-clip-text text-transparent"
          style={{ ...headingStyle, marginBottom: 20 }}>
          People in focus
        </h2>
        <div style={{ display: "grid", gridTemplateColumns: "1fr", gap: 12 }}>
          {PEOPLE.map((p, i) => (
            <div key={i} style={{ background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.1)", borderRadius: 16, padding: "20px 20px 0", display: "flex", flexDirection: "column", position: "relative", overflow: "hidden", minHeight: 240 }}>
              <div style={{ color: "#CE1010", fontSize: "16px", fontWeight: 600, marginBottom: 10, fontFamily: "'Inter', sans-serif" }}>{p.label}</div>
              <div style={{ color: "white", fontSize: "36px", fontWeight: 800, lineHeight: "42px", fontFamily: "'Inter', sans-serif" }}>{p.riskRate}</div>
              <div style={{ color: "white", fontSize: "14px", marginTop: 6, marginBottom: 14 }}>Risk Rate</div>
              <div style={{ color: "white", fontSize: "14px", marginBottom: 8 }}>Mean Age</div>
              <div style={{ color: "white", fontSize: "36px", fontWeight: 800, lineHeight: "42px", fontFamily: "'Inter', sans-serif" }}>{p.meanAge}</div>
              <div style={{ color: "white", fontSize: "14px", marginTop: 8, marginBottom: 20 }}>years</div>
              <img src={p.img} alt={p.label} style={{ position: "absolute", bottom: -10, right: -10, width: "38%", maxWidth: 150, objectFit: "contain", objectPosition: "bottom right", transform: "rotate(10deg)", transformOrigin: "bottom right", opacity: 0.88 }} />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

// ─── Desktop layout: sticky, phase-based ─────────────────────────────────────
function DesktopLayout({ progress }) {
  /*
   * Three phases, each crossfading:
   *   Phase 1 (Part 1): fades in at 0.00, fades out at 0.30
   *   Phase 2 (Part 2): fades in at 0.35, fades out at 0.62
   *   Phase 3 (Part 3): fades in at 0.67, stays
   *
   * With section height 450vh → scrollable = 350vh:
   *   Phase 1 exit  @ 0.30 → 105vh of scroll
   *   Phase 2 entry @ 0.35 → 122vh
   *   Phase 2 exit  @ 0.62 → 217vh
   *   Phase 3 entry @ 0.67 → 234vh
   */

  // Part 1
  const p1In  = ease(clamp(progress / 0.07, 0, 1));
  const p1Out = ease(clamp((progress - 0.30) / 0.06, 0, 1));
  const op1   = p1In * (1 - p1Out);
  const chartAnim  = ease(clamp((progress - 0.03) / 0.07, 0, 1));
  const footerAnim = ease(clamp((progress - 0.08) / 0.07, 0, 1));

  // Part 2
  const p2In  = ease(clamp((progress - 0.35) / 0.08, 0, 1));
  const p2Out = ease(clamp((progress - 0.62) / 0.06, 0, 1));
  const op2   = p2In * (1 - p2Out);
  const cards1Anim = ease(clamp((progress - 0.39) / 0.10, 0, 1));

  // Part 3
  const p3In  = ease(clamp((progress - 0.67) / 0.09, 0, 1));
  const op3   = p3In;
  const cards2Anim = ease(clamp((progress - 0.71) / 0.10, 0, 1));

  const headingStyle = {
    fontFamily: "'Inter', sans-serif",
    fontWeight: 700,
    color: "white",
    textAlign: "center",
    margin: 0,
    // Fluid: looks like the 120px original at 1600px wide, scales down gracefully
    fontSize: "clamp(52px, 7.5vw, 120px)",
    lineHeight: 1.08,
    letterSpacing: "-0.04em",
  };

  // Shared panel wrapper: absolutely fills sticky box, centers content
  const panelBase = (opacity) => ({
    position: "absolute",
    inset: 0,
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    padding: "0 clamp(40px, 5vw, 80px)",
    opacity,
    zIndex: 1,
    // Hide from pointer events when invisible so underlying links don't block
    pointerEvents: opacity < 0.05 ? "none" : "auto",
    transition: "none",
  });

  return (
    <div
      style={{
        position: "sticky",
        top: 0,
        height: "100vh",
        overflow: "hidden",       // ← only hidden, never auto — avoids inner-scroll hijack
        background: "black",
      }}
    >
      {/* Ellipse decoration */}
      <div style={{ position: "absolute", top: 0, right: -430, zIndex: 0, pointerEvents: "none" }}>
        <img src="/assets/Ellipse.png" alt="" style={{ width: "900px", height: "900px" }} />
      </div>

      {/* ══ Phase 1: Fraud / Chart ══ */}
      <div style={panelBase(op1)}>
        <h2 style={{ ...headingStyle, marginBottom: "clamp(10px, 1.2vh, 18px)" }}>
          The Fraud Behind<br />the Workforce
        </h2>
        <p style={{ color: "white", fontSize: "clamp(15px, 1.5vw, 26px)", fontWeight: 600, margin: "0 0 clamp(14px, 2vh, 24px)", textAlign: "center", fontFamily: "'Inter', sans-serif", lineHeight: 1.4 }}>
          India's gig workforce has grown from
        </p>
        <div style={{ width: "100%", maxWidth: "min(840px, 90%)", opacity: chartAnim, transform: `translateY(${lerp(14, 0, chartAnim)}px)` }}>
          <img src="/assets/graph.gif" alt="Gig workforce growth chart" style={{ width: "100%", display: "block", borderRadius: 4 }} />
          <div style={{ textAlign: "center", marginTop: 6, opacity: footerAnim }}>
            <span style={{ color: "rgba(255,255,255,0.38)", fontSize: 13, fontFamily: "'Inter', sans-serif" }}>
              Source:{" "}
              <a href="https://www.niti.gov.in/sites/default/files/2023-06/Policy_Brief_India%27s_Booming_Gig_and_Platform_Economy_27062022.pdf" target="_blank" rel="noreferrer" style={SOURCE_LINK_STYLE}>Niti Ayog</a>
              {" "}and{" "}
              <a href="https://www.livemint.com/money/personal-finance/indias-gig-economy-in-2025-growth-formalisation-and-financial-inclusion-explained-11753438649777.html" target="_blank" rel="noreferrer" style={SOURCE_LINK_STYLE}>Mint</a>
            </span>
          </div>
        </div>
        <p style={{ color: "white", fontSize: "clamp(15px, 1.5vw, 26px)", fontFamily: "'Inter', sans-serif", textAlign: "center", margin: "clamp(10px, 1.5vh, 20px) 0 0", maxWidth: 700, opacity: footerAnim, lineHeight: 1.45 }}>
          But as the workforce expands, fraud scales alongside it.
        </p>
      </div>

      {/* ══ Phase 2: Questions ══ */}
      <div style={panelBase(op2)}>
        <h2 style={{ ...headingStyle, marginBottom: "clamp(24px, 3.5vh, 44px)" }}>
          This section<br />answers questions like
        </h2>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "clamp(10px, 1.2vw, 18px)", width: "100%", maxWidth: 1200 }}>
          {QUESTIONS.map((q, i) => {
            const cp = ease(clamp(cards1Anim - i * 0.10, 0, 1));
            return (
              <div key={i} style={{ backgroundImage: "linear-gradient(#1d1d1d, #212121)", border: "1px solid rgba(255,255,255,0.2)", borderRadius: 16, padding: "clamp(14px, 1.6vh, 22px) clamp(14px, 1.4vw, 22px)", display: "flex", alignItems: "center", gap: "clamp(12px, 1.2vw, 18px)", minHeight: "clamp(88px, 11vh, 110px)", opacity: cp, transform: `translateY(${lerp(20, 0, cp)}px) scale(${lerp(0.97, 1, cp)})` }}>
                <div style={{ width: "clamp(52px, 4.5vw, 68px)", height: "clamp(52px, 4.5vw, 68px)", flexShrink: 0, borderRadius: 12, display: "flex", alignItems: "center", justifyContent: "center" }}>
                  <img src={q.img} alt="" style={{ width: "clamp(80px, 7vw, 120px)", height: "clamp(56px, 5vw, 82px)", objectFit: "contain" }} />
                </div>
                <p style={{ color: "white", fontSize: "clamp(13px, 1.05vw, 17px)", fontWeight: 500, margin: 0, lineHeight: 1.5, fontFamily: "'Inter', sans-serif" }}>{q.text}</p>
              </div>
            );
          })}
        </div>
      </div>

      {/* ══ Phase 3: People in focus ══ */}
      <div style={panelBase(op3)}>
        <h2
          className="bg-gradient-to-r from-[#cdcdcd] to-white bg-clip-text text-transparent"
          style={{ ...headingStyle, marginBottom: "clamp(24px, 3.5vh, 44px)" }}
        >
          People in focus
        </h2>
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "clamp(10px, 1.2vw, 18px)", width: "100%", maxWidth: 1200 }}>
          {PEOPLE.map((p, i) => {
            const cp = ease(clamp(cards2Anim - i * 0.08, 0, 1));
            return (
              <div key={i} style={{ background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.1)", borderRadius: 16, padding: "clamp(20px, 2.5vh, 32px) clamp(20px, 2vw, 32px) 0", display: "flex", flexDirection: "column", position: "relative", overflow: "hidden", height: "clamp(260px, 34vh, 360px)", opacity: cp, transform: `translateY(${lerp(20, 0, cp)}px)` }}>
                <div style={{ color: "#CE1010", fontSize: "clamp(14px, 1.15vw, 20px)", fontWeight: 600, marginBottom: "clamp(10px, 1.4vh, 16px)", fontFamily: "'Inter', sans-serif" }}>{p.label}</div>
                <div style={{ color: "white", fontSize: "clamp(38px, 4.2vw, 62px)", fontWeight: 800, lineHeight: 1, fontFamily: "'Inter', sans-serif" }}>{p.riskRate}</div>
                <div style={{ color: "white", fontSize: "clamp(13px, 1.05vw, 17px)", marginTop: "clamp(4px, 0.7vh, 8px)", marginBottom: "clamp(12px, 2vh, 22px)" }}>Risk Rate</div>
                <div style={{ color: "white", fontSize: "clamp(13px, 1.05vw, 17px)", marginBottom: "clamp(4px, 0.7vh, 8px)" }}>Mean Age</div>
                <div style={{ color: "white", fontSize: "clamp(38px, 4.2vw, 62px)", fontWeight: 800, lineHeight: 1, fontFamily: "'Inter', sans-serif" }}>{p.meanAge}</div>
                <div style={{ color: "white", fontSize: "clamp(13px, 1.05vw, 17px)", marginTop: "clamp(4px, 0.7vh, 8px)", marginBottom: 20 }}>years</div>
                <img src={p.img} alt={p.label} style={{ position: "absolute", bottom: -10, right: -10, width: "38%", maxWidth: 150, objectFit: "contain", objectPosition: "bottom right", transform: "rotate(10deg)", transformOrigin: "bottom right", opacity: 0.88 }} />
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ─── Root component ───────────────────────────────────────────────────────────
export default function FraudSection() {
  const [progress, setProgress] = useState(0);
  const [isMobile, setIsMobile] = useState(false);
  const sectionRef = useRef(null);

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 768);
    check();
    window.addEventListener("resize", check, { passive: true });
    return () => window.removeEventListener("resize", check);
  }, []);

  useEffect(() => {
    if (isMobile) return;
    const onScroll = () => {
      const el = sectionRef.current;
      if (!el) return;
      const scrollable = el.offsetHeight - window.innerHeight;
      if (scrollable <= 0) return;
      const p = clamp(-el.getBoundingClientRect().top / scrollable, 0, 1);
      setProgress(p);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll(); // seed on mount
    return () => window.removeEventListener("scroll", onScroll);
  }, [isMobile]);

  if (isMobile) {
    // Mobile: no sticky wrapper — plain static layout, exactly as before
    return (
      <div ref={sectionRef}>
        <MobileLayout />
      </div>
    );
  }

  // Desktop: 450vh outer scroll container → 350vh of scroll range for 3 phases
  return (
    <div ref={sectionRef} style={{ height: "450vh", position: "relative" }}>
      <DesktopLayout progress={progress} />
    </div>
  );
}
